import * as THREE from './vendor/three.module.js';
export const LIGHTNING_WHIP=Object.freeze({range:8,arc:110,damage:180,cost:15,cooldown:1.2,windup:.08,sweep:.3,recovery:.12,radius:.3});
const up=new THREE.Vector3(0,1,0),axis=new THREE.Vector3(0,1,0);
// One paid swing; collision samples the entire swept angle, including slow frames.
export class RunnerWhip {
 constructor(scene){this.root=new THREE.Group();scene.add(this.root);this.dummy=new THREE.Object3D();this.links=new THREE.InstancedMesh(new THREE.CylinderGeometry(1,1,1,5),new THREE.MeshBasicMaterial({color:'#cfffff',toneMapped:false}),20);this.glow=new THREE.InstancedMesh(this.links.geometry,new THREE.MeshBasicMaterial({color:'#38cfff',transparent:true,opacity:.25,depthWrite:false,blending:THREE.AdditiveBlending}),20);this.links.frustumCulled=this.glow.frustumCulled=false;this.root.add(this.links,this.glow);this.lines=new THREE.LineSegments(new THREE.BufferGeometry().setAttribute('position',new THREE.BufferAttribute(new Float32Array(20*6*4),3)),new THREE.LineBasicMaterial({color:'#70eeff',transparent:true,opacity:.8,depthWrite:false,toneMapped:false}));this.lines.frustumCulled=false;this.root.add(this.lines);this.tip=new THREE.Mesh(new THREE.IcosahedronGeometry(.16,1),new THREE.MeshBasicMaterial({color:'#edffff',toneMapped:false}));this.root.add(this.tip);this.reset();}
 reset(){this.cancel();this.cooldown=0;this.swings=0;this.hits=0;this.damage=0;this.lastHits=[];}
 cancel(){this.active=false;this.age=0;this.sampled=-1;this.touched=new Set();this.shieldContacts=new Map();if(this.root)this.root.visible=false;}
 start(energy,direction,normal=up){if(this.active||this.cooldown>1e-8||!energy.spend(LIGHTNING_WHIP.cost))return false;this.active=true;this.age=0;this.sampled=-1;this.touched.clear();this.shieldContacts.clear();this.lastHits=[];this.forward=direction.clone().normalize();this.normal=normal.clone().normalize();this.cooldown=LIGHTNING_WHIP.cooldown;this.swings++;return true;}
 get progress(){return THREE.MathUtils.clamp((this.age-LIGHTNING_WHIP.windup)/LIGHTNING_WHIP.sweep,0,1);}
 direction(t=this.progress){return this.forward.clone().applyAxisAngle(this.normal,THREE.MathUtils.degToRad(LIGHTNING_WHIP.arc)*(.5-t));}
 curve(from,t,time=0){const dir=this.direction(t),side=new THREE.Vector3().crossVectors(this.normal,dir).normalize(),length=LIGHTNING_WHIP.range*(.22+.78*Math.sin(Math.PI*Math.min(1,.14+t*.86))**.35);return Array.from({length:21},(_,i)=>{const u=i/20,p=from.clone().addScaledVector(dir,length*u);p.addScaledVector(side,Math.sin(u*Math.PI)*(.65+Math.sin(t*Math.PI)*.45));p.addScaledVector(this.normal,Math.sin(u*Math.PI)*.12);if(i>0&&i<20){p.addScaledVector(side,Math.sin(i*19+Math.floor(time*45))*u*.10);p.addScaledVector(this.normal,Math.cos(i*13+Math.floor(time*45))*u*.07);}return p;});}
 strike(hit,onHit){const key=hit.unit||hit.missile||hit.section;if(!key||this.touched.has(key))return;this.touched.add(key);this.shieldContacts.delete(key);const result=onHit(hit,LIGHTNING_WHIP.damage)||{};this.damage+=result.damage||0;this.hits++;this.lastHits.push({id:key.id||key.building||'surface',damage:result.damage||0});}
 update(dt,time,{from,trace,onHit}){this.cooldown=Math.max(0,this.cooldown-dt);if(!this.active)return;const c=LIGHTNING_WHIP;this.age+=dt;const t=this.progress;
  if(this.age>=c.windup&&this.sampled<1){const start=Math.max(0,this.sampled),steps=Math.max(1,Math.ceil((t-start)*c.arc/5));for(let j=this.sampled<0?0:1;j<=steps;j++){const path=this.curve(from,THREE.MathUtils.lerp(start,t,j/steps),time);for(let i=1;i<path.length;i++){const hit=trace(path[i-1],path[i],c.radius);if(!hit)continue;const key=hit.unit||hit.missile||hit.section;if(key&&!this.touched.has(key)){if(hit.part==='shield')this.shieldContacts.set(key,hit);else this.strike(hit,onHit);}break;}}this.sampled=t;if(t>=1)for(const hit of [...this.shieldContacts.values()])this.strike(hit,onHit);}
  const ending=this.age>c.windup+c.sweep,fade=ending?Math.max(0,1-(this.age-c.windup-c.sweep)/c.recovery):1;this.root.visible=true;const path=this.curve(from,t,time),visible=[];for(let i=1;i<path.length;i++){const hit=trace(path[i-1],path[i],c.radius);visible.push([path[i-1],hit?new THREE.Vector3().copy(hit.point):path[i]]);if(hit)break;}
  this.links.count=this.glow.count=visible.length;const a=this.lines.geometry.attributes.position;let k=0;for(let i=0;i<visible.length;i++){const[p,q]=visible[i],v=q.clone().sub(p),r=(.025+.035*(1-i/20))*fade;this.dummy.position.copy(p).lerp(q,.5);this.dummy.quaternion.setFromUnitVectors(up,v.clone().normalize());this.dummy.scale.set(r,v.length(),r);this.dummy.updateMatrix();this.links.setMatrixAt(i,this.dummy.matrix);this.dummy.scale.x=this.dummy.scale.z=r*3.5;this.dummy.updateMatrix();this.glow.setMatrixAt(i,this.dummy.matrix);for(let j=0;j<2;j++){const x=p.clone().addScaledVector(axis,Math.sin(time*80+i*7+j)*.12),y=q.clone().addScaledVector(axis,Math.cos(time*70+i*3+j)*.12);a.setXYZ(k++,x.x,x.y,x.z);a.setXYZ(k++,y.x,y.y,y.z);}}
  this.links.instanceMatrix.needsUpdate=this.glow.instanceMatrix.needsUpdate=true;a.needsUpdate=true;this.lines.geometry.setDrawRange(0,k);this.lines.material.opacity=.8*fade;this.tip.position.copy(visible.at(-1)?.[1]||from);this.tip.scale.setScalar(fade*(1+Math.sin(time*90)*.2));if(this.age>=c.windup+c.sweep+c.recovery)this.cancel();
 }
 diagnostics(){return{active:this.active,progress:this.progress,cooldown:this.cooldown,swings:this.swings,hits:this.hits,damage:this.damage,lastHits:this.lastHits,range:LIGHTNING_WHIP.range,cost:LIGHTNING_WHIP.cost};}
}
